module.exports = /*#__PURE__*/JSON.parse('{"title":"How to Integrate Push Universal Wallets?","description":"Turn a generic wallet popup into a fully branded universal wallet layer for your cross-chain app — no custom glue per chain required.","frontMatter":{"slug":"integrate-push-universal-wallets","title":"How to Integrate Push Universal Wallets?","authors":["push"],"image":"./cover-image.webp","description":"Turn a generic wallet popup into a fully branded universal wallet layer for your cross-chain app — no custom glue per chain required.","text":"Turn a generic wallet popup into a fully branded universal wallet layer for your cross-chain app — no custom glue per chain required. Here\'s how to customize it in 3 steps.","tags":["Maker Monday"]},"content":{"id":"integrate-push-universal-wallets","metadata":{"permalink":"/push-chain-website/pr-preview/pr-1234/blog/integrate-push-universal-wallets","source":"@site/blog/2025-12-01-integrate-push-universal-wallets/index.md","title":"How to Integrate Push Universal Wallets?","description":"Turn a generic wallet popup into a fully branded universal wallet layer for your cross-chain app — no custom glue per chain required.","date":"2025-12-01T00:00:00.000Z","tags":[{"inline":true,"label":"Maker Monday","permalink":"/push-chain-website/pr-preview/pr-1234/blog/tags/maker-monday"}],"readingTime":0.93,"hasTruncateMarker":true,"authors":[{"name":"Push Chain","url":"https://x.com/PushChain","page":{"permalink":"/push-chain-website/pr-preview/pr-1234/blog/authors/push"},"imageURL":"/push-chain-website/pr-preview/pr-1234/assets/blog/authors/authorpush.png","key":"push"}],"frontMatter":{"slug":"integrate-push-universal-wallets","title":"How to Integrate Push Universal Wallets?","authors":["push"],"image":"./cover-image.webp","description":"Turn a generic wallet popup into a fully branded universal wallet layer for your cross-chain app — no custom glue per chain required.","text":"Turn a generic wallet popup into a fully branded universal wallet layer for your cross-chain app — no custom glue per chain required. Here\'s how to customize it in 3 steps.","tags":["Maker Monday"]},"unlisted":false,"prevItem":{"title":"What is Universal Fee Abstraction?","permalink":"/push-chain-website/pr-preview/pr-1234/blog/what-is-universal-abstraction"},"nextItem":{"title":"A Universal Era Begins. Introducing Push Chain’s Donut Testnet 🍩","permalink":"/push-chain-website/pr-preview/pr-1234/blog/introducing-push-chains-donut-testnet"}},"content":"![Cover Image of How to Integrate Push Universal Wallets](./cover-image.webp)\\n\\n<!--truncate-->\\n\\nThe biggest maker or breaker for any cross-chain app is its wallet UX.\\n\\nMost apps still ship a generic \\"Connect Wallet\\" popup that looks bolted on.\\nWith Push Universal Wallet, the wallet becomes part of your product.\\n\\nYou control the branding, the flows and the chains.\\n\\nHere is how to customize it.\\n\\n## Step 1: Add one provider\\n\\n[`PushUniversalWalletProvider`](https://push.org/docs/chain/ui-kit/integrate-push-universal-wallet/) becomes your app\'s wallet brain:\\n\\n- Works across EVM, Solana and Push Chain\\n- Tracks connection, chain and account state in one place\\n- Applies your app name, logo and theme for every user\\n\\nNo wiring three different connection systems.\\n\\n## Step 2: Control the wallet experience\\n\\nWith [`PushUniversalAccountButton`](https://push.org/docs/chain/ui-kit/) and hooks like `usePushWalletContext` and `usePushChainClient` you can:\\n\\n- Decide when the wallet opens\\n- Check if the user is connected\\n- Access the already initialized Core SDK for the user\'s connected chain\\n- Pre wire Universal Transactions into your flows\\n\\nYou go from connected to ready to send tx or messages without custom glue per chain.\\n\\n## Step 3: Make it look like your product\\n\\nIn the UI Kit theme you can override:\\n- Colors\\n- Radii\\n- Typography\\n- Light or dark mode defaults\\nOr just style the button.\\n\\nSame engine, your brand.\\n\\nCheck out these live [playground examples](https://push.org/docs/chain/ui-kit/).\\n\\n💫 That\'s it. You just turned a generic wallet popup into a custom universal wallet layer.\\n\\n🚫 No separate EVM or Solana logic\\n🚫 No per chain connection flows\\n🚫 No hand-rolled modals\\n🚫 No signer juggling\\n\\nJust one wallet that looks and feels like your app.\\n\\n🦦 The Push way to build."},"twitterId":""}');

